responseBody:
body {
    background-color: #0a0a0b;
    color: #d1d1d1;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    margin: 0;
    display: flex;
    justify-content: center;
}

#app {
    width: 100%;
    max-width: 800px;
    padding: 2rem;
}

header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid #333;
    padding-bottom: 1rem;
    margin-bottom: 2rem;
}

h1 {
    font-size: 1.5rem;
    color: #00ffcc;
    text-transform: uppercase;
    letter-spacing: 2px;
}

.dashboard {
    display: flex;
    gap: 1rem;
    font-family: monospace;
    font-size: 0.8rem;
    color: #00ffcc;
}

.metric span {
    color: #fff;
}

.story-text {
    font-size: 1.2rem;
    line-height: 1.6;
    margin-bottom: 2rem;
    animation: fadeIn 1s ease-in;
}

.choices-container {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

button {
    background: transparent;
    border: 1px solid #00ffcc;
    color: #00ffcc;
    padding: 0.8rem 1.2rem;
    cursor: pointer;
    font-size: 1rem;
    transition: all 0.3s;
    text-align: left;
}

button:hover {
    background: #00ffcc;
    color: #0a0a0b;
}

#interactive-zone {
    margin-bottom: 2rem;
    padding: 1rem;
    background: #161618;
    border-left: 4px solid #00ffcc;
}

.code-playground {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.code-editor {
    background: #000;
    color: #fff;
    padding: 1rem;
    font-family: monospace;
    white-space: pre-wrap;
    border: 1px solid #333;
}

.run-btn {
    background: #00ffcc;
    color: #0a0a0b;
    font-weight: bold;
    text-align: center;
}

.output {
    margin-top: 1rem;
    padding: 0.5rem;
    background: #000;
    color: #00ff00;
    font-family: monospace;
    font-size: 0.9rem;
    border: 1px solid #00ff00;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}
