function renderInteractiveElement(element) {
    if (element.type === 'code_snippet') {
        const div = document.createElement('div');
        div.className = 'code-playground';
        div.innerHTML = `
            <h3 style='color:#00ffcc'>${element.description}</h3>
            <div id='monaco-container' class='monaco-editor-container'></div>
            <button class='run-btn'>Execute WASM Logic</button>
            <div id='code-output'></div>
        `;
        document.getElementById('interactive-zone').appendChild(div);

        require.config({ paths: { 'vs': 'https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.44.0/min/vs' } });
        require(['vs/editor/editor.main'], function() {
            const editor = monaco.editor.create(document.getElementById('monaco-container'), {
                value: element.initialCode,
                language: 'go',
                theme: 'vs-dark',
                automaticLayout: true,
                minimap: { enabled: false }
            });

            div.querySelector('.run-btn').onclick = async () => {
                const code = editor.getValue();
                const outputDiv = div.querySelector('#code-output');
                outputDiv.innerHTML = 'Compiling to WASM...';

                // Validation Logic as per Build Plan (Surgical check for sync.Pool and zero-copy)
                const hasSyncPool = code.includes('sync.Pool');
                const hasZeroCopy = code.includes('make([]byte') && !code.includes('copy(');

                setTimeout(async () => {
                    if (hasSyncPool && hasZeroCopy) {
                        outputDiv.innerHTML = `<div class='output'>[WASM SUCCESS] Binary checksum valid. Zero-copy pattern matches AF_XDP requirements.</div>`;
                        await window.CognoscentBridge.bridgeChoice(1, 1); // Advance narrative
                    } else {
                        outputDiv.innerHTML = `<div class='output' style='color:red'>[WASM ERROR] Runtime panic: Memory leak detected in FramePool.</div>`;
                    }
                }, 1000);
            };
        });
    } else if (element.type === 'governance_vote') {
        const div = document.createElement('div');
        div.className = 'gov-vote-panel';
        div.innerHTML = `
            <h3 style='color:#00ffcc'>Governance Proposal: ${element.proposalId}</h3>
            <p>${element.description}</p>
            <div class='vote-options'>
                ${element.options.map((opt, i) => `<button class='vote-btn' data-index='${i}'>${opt.text}</button>`).join('')}
            </div>
            <div id='vote-result'></div>
        `;
        document.getElementById('interactive-zone').appendChild(div);

        div.querySelectorAll('.vote-btn').forEach(btn => {
            btn.onclick = async () => {
                const index = btn.dataset.index;
                const result = await window.CognoscentBridge.bridgeChoice(2, index);
                div.querySelector('#vote-result').innerHTML = `<div class='output'>Vote Recorded. The network is adjusting...</div>`;
                btn.disabled = true;
            };
        });
    }
}

// Provide a placeholder renderer for forensic tools used by chapters.
function renderForensicTool(element) {
    const div = document.createElement('div');
    div.className = 'forensic-tool';
    div.innerHTML = `
        <h3 style='color:#00ffcc'>Forensic Tool</h3>
        <p>${element.description || 'Analyze mirror-layer shims and diffs.'}</p>
        <pre class='forensics-output'>${element.initialCode || ''}</pre>
    `;
    document.getElementById('interactive-zone').appendChild(div);
}

// Expose to window so other scripts can call it if needed
window.renderForensicTool = window.renderForensicTool || renderForensicTool;

// Provide placeholder renderers for extended interactive elements.
function renderGovernanceModule(element) {
    const div = document.createElement('div');
    div.className = 'gov-module';
    div.innerHTML = `<h3 style='color:#00ffcc'>Governance Module</h3><p>${element.description||''}</p>`;
    document.getElementById('interactive-zone').appendChild(div);
}

function renderCodeReview(element) {
    const div = document.createElement('div');
    div.className = 'code-review';
    div.innerHTML = `<h3 style='color:#00ffcc'>Code Review</h3><p>${element.description||''}</p>`;
    document.getElementById('interactive-zone').appendChild(div);
}

function renderQuantumSimulator(element) {
    const div = document.createElement('div');
    div.className = 'quantum-sim';
    div.innerHTML = `<h3 style='color:#00ffcc'>Quantum Simulator</h3><p>${element.description||''}</p>`;
    document.getElementById('interactive-zone').appendChild(div);
}

// Expose to window
window.renderGovernanceModule = window.renderGovernanceModule || renderGovernanceModule;
window.renderCodeReview = window.renderCodeReview || renderCodeReview;
window.renderQuantumSimulator = window.renderQuantumSimulator || renderQuantumSimulator;

const API_BASE = 'http://localhost:3001';
const USER_ID = 'reader-' + Math.random().toString(36).substr(2, 9);

async function bridgeChoice(chapterId, choiceIndex) {
    const response = await fetch(`${API_BASE}/choice`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: USER_ID, chapterId, choiceIndex })
    });
    return await response.json();
}

async function fetchChapter(id) {
    const response = await fetch(`${API_BASE}/chapter/${id}`);
    return await response.json();
}

window.CognoscentBridge = {
    bridgeChoice,
    fetchChapter,
    userId: USER_ID
};

// Simple state manager for the frontend
let state = {
    currentChapterId: 1,
    progress: {}
};

async function loadChapter(id) {
    state.currentChapterId = id;
    const chapter = await fetchChapter(id);

    const storyText = document.getElementById('story-text');
    const choicesContainer = document.getElementById('choices-container');
    const interactiveZone = document.getElementById('interactive-zone');

    if (!chapter) return;

    storyText.innerText = chapter.text;
    choicesContainer.innerHTML = '';
    interactiveZone.innerHTML = '';

    if (chapter.interactiveElement) {
        renderInteractiveElement(chapter.interactiveElement);
    }

    chapter.choices.forEach((choice, index) => {
        const btn = document.createElement('button');
        btn.innerText = choice.text;
        btn.onclick = async () => {
            await bridgeChoice(id, index);
            loadChapter(choice.nextChapter);
        };
        choicesContainer.appendChild(btn);
    });
}

document.addEventListener('DOMContentLoaded', () => {
    loadChapter(1);
});

